"use client";

import { FormEvent, useEffect, useState } from "react";
import { Button, Header, HeaderGlobalAction, HeaderGlobalBar, HeaderMenuButton, HeaderName, SideNav, SideNavItems, SideNavLink, SkipToContent, Tag, Theme } from "@carbon/react";
import { Add, Analytics, ArrowRight, Asleep, Chat, Close, Dashboard, Document, Launch, Menu, Settings, UserAvatar } from "@carbon/icons-react";
import { CarbonCapabilityChart } from "./CarbonVisuals";

type Priority = "Alta" | "Média" | "Baixa";
type Evidence = { sourceType: string; sourceId: string; title: string; excerpt: string; occurredAt: string };
type Score = { name: string; short: string; alignment: number; value: number; readiness: number; confidence: number; level: Priority; evidence: string[]; action: string };
type Insight = { summary: string; signals: string[]; ibmThemes: string[]; nextQuestions: string[]; nextActions: string[]; risks: string[]; stakeholders: string[]; systems: string[]; painPoints: string[]; aiStatus: "watsonx" | "fallback" | "error" };
type Meeting = { id: string; discoveryId: string; title: string; notes: string; summary: string; insights: Insight; aiStatus: string; createdAt: string; scheduledAt?: string | null; attendees?: string[]; objective?: string; meetingStatus?: string };
type Stakeholder = { id: string; discoveryId: string; name: string; role: string; area: string; reportsToId: string | null; influence: "Alta" | "Média" | "Baixa"; stance: "Aliado" | "Neutro" | "Resistente" | "Desconhecido"; priorities: string[]; notes: string; source: "manual" | "suggested"; createdAt: string; updatedAt: string };
type Discovery = { id: string; customerName: string; industry: string; companySize: string; owner: string; visibility: string; stage: string; progress: number; priority: Priority; challengeSummary: string; answers: Array<{ key: string; question: string; answer: string; at: string }>; meetings: Meeting[]; scores: Score[]; recommendations: Array<{ type: string; name: string; rationale: string }>; nextEngagement: string; updatedAt: string };
type AccountEvent = { id: string; discoveryId: string; type: string; title: string; content: string; sourceType: string; sourceId: string | null; evidenceStatus: "confirmed" | "assumption" | "gap" | "stale"; confidence: number; occurredAt: string };
type Memory = { discoveryId: string; executiveSummary: string; known: string[]; assumptions: string[]; gaps: string[]; changes: string[]; aiStatus: string; version: number; updatedAt: string };
type Action = { id: string; discoveryId: string; stakeholderId: string | null; type: string; title: string; rationale: string; nextStep: string; impact: number; urgency: number; confidence: number; maturity: number; priorityScore: number; status: string; dueAt: string | null; evidence: Evidence[] };
type Hypothesis = { id: string; discoveryId: string; capabilityKey: string; title: string; problem: string; products: string[]; stakeholderIds: string[]; evidence: Evidence[]; gaps: string[]; confidence: number; stage: string; nextStep: string };
type Plan = { discoveryId: string; priorities: string[]; initiatives: string[]; objectives: string[]; risks: string[]; ecosystem: string[]; relationship: string[]; plan30: string[]; plan60: string[]; plan90: string[]; approvalStatus: string; suggestion: Record<string, string[]>; updatedAt: string };
type AccountDocument = { id: string; discoveryId: string; name: string; contentType: string; sizeBytes: number; status: string; summary: string; createdAt: string };
type ChatMessage = { id: string; discoveryId: string; role: string; content: string; citations: Evidence[]; aiStatus: string; createdAt: string };
type ApiData = { discoveries: Discovery[]; meetings: Meeting[]; stakeholders: Stakeholder[]; events: Array<{ id: string; discoveryId: string; type: string; detail: string; createdAt: string }>; accountEvents: AccountEvent[]; memories: Memory[]; actions: Action[]; hypotheses: Hypothesis[]; plans: Plan[]; documents: AccountDocument[]; chats: ChatMessage[]; aiRuns: Array<{ id: string; discoveryId: string; agent: string; provider: string; status: string; confidence: number; validated: boolean; detail: string; createdAt: string }> };

const emptyData: ApiData = { discoveries: [], meetings: [], stakeholders: [], events: [], accountEvents: [], memories: [], actions: [], hypotheses: [], plans: [], documents: [], chats: [], aiRuns: [] };
const nav = [{ id: "home", label: "Início", icon: Dashboard }, { id: "accounts", label: "Inteligência de contas", icon: Document }, { id: "radar", label: "Radar da carteira", icon: Analytics }, { id: "settings", label: "Configurações", icon: Settings }] as const;
const tabs = [{ id: "summary", label: "Resumo" }, { id: "memory", label: "Contexto e memória" }, { id: "meetings", label: "Reuniões" }, { id: "stakeholders", label: "Stakeholders" }, { id: "themes", label: "Temas IBM" }, { id: "plan", label: "Account Plan" }] as const;
const questions = [
  ["trigger", "O que abriu essa conversa agora e qual pressão de negócio existe por trás?"], ["stakeholders", "Quem participa da decisão e quem sente a dor no dia a dia?"], ["landscape", "Quais sistemas, clouds, dados ou aplicações críticas apareceram?"], ["pain", "Onde existe perda de dinheiro, risco, produtividade, confiança ou velocidade?"], ["data-ai", "Quais iniciativas de IA, analytics ou dados confiáveis estão em andamento?"], ["readiness", "Existe sponsor, orçamento, timeline e critério claro para avançar?"], ["crm-fit", "O que falta validar antes de criar uma oportunidade no CRM?"],
] as const;
const playbooks = [
  { key: "FinOps", product: "IBM Cloudability + Turbonomic", question: "Como custos são alocados por produto e quem aprova otimizações?", pitch: "Transparência financeira e otimização contínua sem degradar performance.", workshop: "FinOps Discovery Workshop" },
  { key: "Trusted Data", product: "watsonx.data + IBM Guardium", question: "Quais fontes são críticas e onde existem dados sensíveis?", pitch: "Fundação governada para analytics e IA com proteção de dados.", workshop: "Trusted Data Workshop" },
  { key: "AI Governance", product: "watsonx.governance + watsonx.ai", question: "Como modelos, riscos e evidências são aprovados?", pitch: "Governança do ciclo de vida de IA com supervisão humana.", workshop: "AI Governance Workshop" },
  { key: "Hybrid Cloud", product: "Red Hat OpenShift + Terraform", question: "Quais workloads exigem portabilidade e consistência?", pitch: "Plataforma e automação consistentes em ambientes híbridos.", workshop: "Hybrid Cloud Architecture Review" },
  { key: "Automation", product: "watsonx Orchestrate + IBM Concert", question: "Quais tarefas e decisões se repetem toda semana?", pitch: "Orquestração de trabalho conectada a insights operacionais.", workshop: "Automation Discovery Workshop" },
  { key: "App Modernization", product: "OpenShift + Instana", question: "Quais aplicações seguram o roadmap de negócio?", pitch: "Modernização priorizada por valor, risco e esforço.", workshop: "Modernization Assessment" },
];

const formatDate = (value?: string | null) => value ? new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "short", year: "numeric" }).format(new Date(value)) : "Sem prazo";
const statusLabel: Record<string, string> = { proposal: "Proposta", accepted: "Aceita", in_progress: "Em andamento", completed: "Concluída", discarded: "Descartada", draft: "Rascunho", validating: "Em validação", qualified: "Qualificada" };
const statusType = (status: string) => status === "qualified" || status === "completed" ? "green" : status === "discarded" ? "gray" : status === "in_progress" ? "cyan" : status === "accepted" ? "blue" : "purple";

export default function Home({ mode = "demo", userName = "Visitante" }: { mode?: "demo" | "private"; userName?: string }) {
  const privateMode = mode === "private";
  const [active, setActive] = useState("home"); const [tab, setTab] = useState("summary"); const [data, setData] = useState<ApiData>(emptyData); const [selectedId, setSelectedId] = useState(""); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [mobileNav, setMobileNav] = useState(false); const [notice, setNotice] = useState(""); const [showAdd, setShowAdd] = useState(false); const [showNew, setShowNew] = useState(false); const [copilot, setCopilot] = useState(false); const [question, setQuestion] = useState(""); const [chatResult, setChatResult] = useState<{ answer: string; citations: Evidence[]; confidence: number; aiStatus: string; suggestedActions: string[] } | null>(null); const [selectedStakeholderId, setSelectedStakeholderId] = useState(""); const [showStakeholder, setShowStakeholder] = useState(false); const [editStakeholder, setEditStakeholder] = useState<Stakeholder | null>(null); const [collapsed, setCollapsed] = useState<Set<string>>(new Set());
  const endpoint = `/api/accounts?scope=${mode}`;
  const load = async () => { const response = await fetch(endpoint, { cache: "no-store" }); if (!response.ok) { setLoading(false); return; } const payload = await response.json() as ApiData; setData({ ...emptyData, ...payload }); setSelectedId((current) => current && payload.discoveries.some((item) => item.id === current) ? current : payload.discoveries[0]?.id || ""); setLoading(false); };
  useEffect(() => { let cancelled = false; void fetch(endpoint, { cache: "no-store" }).then(async (response) => response.ok ? response.json() as Promise<ApiData> : emptyData).then((payload) => { if (cancelled) return; setData({ ...emptyData, ...payload }); setSelectedId(payload.discoveries[0]?.id || ""); setLoading(false); }); return () => { cancelled = true; }; }, [endpoint]);
  const selected = data.discoveries.find((item) => item.id === selectedId) || data.discoveries[0]; const accountEvents = data.accountEvents.filter((item) => item.discoveryId === selected?.id); const memory = data.memories.find((item) => item.discoveryId === selected?.id); const actions = data.actions.filter((item) => item.discoveryId === selected?.id); const hypotheses = data.hypotheses.filter((item) => item.discoveryId === selected?.id); const stakeholders = data.stakeholders.filter((item) => item.discoveryId === selected?.id); const meetings = data.meetings.filter((item) => item.discoveryId === selected?.id); const plan = data.plans.find((item) => item.discoveryId === selected?.id); const documents = data.documents.filter((item) => item.discoveryId === selected?.id);
  const portfolioActions = [...data.actions].filter((item) => item.status !== "discarded" && item.status !== "completed").sort((a, b) => b.priorityScore - a.priorityScore); const attention = data.discoveries.filter((item) => item.progress < 55 || data.actions.some((action) => action.discoveryId === item.id && action.priorityScore >= 75)); const stakeholder = stakeholders.find((item) => item.id === selectedStakeholderId) || stakeholders[0];
  const notify = (value: string) => { setNotice(value); window.setTimeout(() => setNotice(""), 3500); };
  const post = async (body: Record<string, unknown>) => fetch("/api/accounts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...body, scope: mode }) });
  const mutate = async (body: Record<string, unknown>, success: string) => { if (!privateMode) { window.location.assign("/signin-with-chatgpt?return_to=%2Fworkspace"); return; } setSaving(true); const response = await post(body); const payload = await response.json() as { error?: string }; if (response.ok) { await load(); notify(success); } else notify(payload.error || "Não foi possível concluir a ação."); setSaving(false); };
  const openAccount = (id: string, nextTab = "summary") => { setSelectedId(id); setActive("accounts"); setTab(nextTab); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const ask = async (event: FormEvent) => { event.preventDefault(); if (!selected || !question.trim()) return; if (!privateMode) { setChatResult({ answer: "Entre no workspace privado para conversar com a memória de uma conta real. Na demonstração, explore as evidências e hipóteses sintéticas.", citations: [], confidence: 100, aiStatus: "demo", suggestedActions: [] }); return; } setSaving(true); const response = await post({ action: "ask", id: selected.id, question }); const payload = await response.json() as { answer: string; citations: Evidence[]; confidence: number; aiStatus: string; suggestedActions: string[]; error?: string }; if (response.ok) setChatResult(payload); else notify(payload.error || "Não foi possível responder."); setSaving(false); };

  if (loading) return <main className="v4-loading"><span>watson</span><p>Organizando a inteligência das contas…</p></main>;
  return <div className={`v4-shell ${copilot ? "copilot-open" : ""}`}>
    <Theme theme="g100"><Header aria-label="watson Account Intelligence" className="v4-header"><SkipToContent /><HeaderMenuButton aria-label="Menu" isActive={mobileNav} onClick={() => setMobileNav(!mobileNav)} renderMenuIcon={<Menu />} renderCloseIcon={<Close />} /><HeaderName prefix="watson" href="#" onClick={(event) => { event.preventDefault(); setActive("home"); }}>Account Intelligence</HeaderName><div className="v4-product-state"><i /> Antes do CRM</div><HeaderGlobalBar><HeaderGlobalAction aria-label="Pergunte sobre esta conta" onClick={() => setCopilot(!copilot)}><Chat /></HeaderGlobalAction><HeaderGlobalAction aria-label={userName}><UserAvatar /></HeaderGlobalAction></HeaderGlobalBar></Header>
      <SideNav aria-label="Navegação principal" expanded={mobileNav} isPersistent={false} isFixedNav onOverlayClick={() => setMobileNav(false)} className="v4-sidenav"><SideNavItems><p className="v4-nav-label">Workspace</p>{nav.map((item) => <SideNavLink key={item.id} href="#" renderIcon={item.icon} isActive={active === item.id} onClick={(event) => { event.preventDefault(); setActive(item.id); setMobileNav(false); }}>{item.label}</SideNavLink>)}</SideNavItems><div className="v4-side-foot"><span>V4 · Proactive intelligence</span><small>{privateMode ? "Workspace privado" : "Demonstração pública"}</small></div></SideNav>
    </Theme>
    <main className="v4-main" id="main-content">{notice && <div className="v4-toast" role="status">{notice}</div>}
      <div className="v4-topbar"><div><span>{privateMode ? `Olá, ${userName.split(" ")[0]}` : "Demonstração pública"}</span><strong>{active === "home" ? "Seu controle operacional" : nav.find((item) => item.id === active)?.label}</strong></div><div>{selected && active !== "home" && <label className="v4-account-switch"><span>Conta</span><select value={selected.id} onChange={(event) => openAccount(event.target.value, tab)}>{data.discoveries.map((item) => <option key={item.id} value={item.id}>{item.customerName}</option>)}</select></label>}<Button kind="secondary" renderIcon={Add} onClick={() => privateMode ? selected ? setShowAdd(true) : setShowNew(true) : window.location.assign("/signin-with-chatgpt?return_to=%2Fworkspace")}>{privateMode && !selected ? "Nova conta" : "Adicionar informação"}</Button></div></div>

      {active === "home" && <section className="v4-page"><header className="v4-page-heading"><div><span>Briefing diário</span><h1>Onde sua atenção gera mais valor hoje</h1><p>A plataforma conecta sinais, relações e maturidade para propor próximos passos — sempre sujeitos à sua aprovação.</p></div>{!privateMode && <a className="v4-primary-link" href="/signin-with-chatgpt?return_to=%2Fworkspace">Acessar workspace <Launch /></a>}</header>
        <div className="v4-brief-grid"><article className="v4-brief-main"><span>Prioridade do dia</span><h2>{portfolioActions[0]?.title || "A carteira está em dia"}</h2><p>{portfolioActions[0]?.rationale || "Adicione uma informação para recalcular sinais e próximos passos."}</p>{portfolioActions[0] && <button onClick={() => openAccount(portfolioActions[0].discoveryId, "summary")}>Abrir conta <ArrowRight /></button>}</article><Metric label="Ações propostas" value={portfolioActions.length} detail="Ordenadas por impacto, urgência, confiança e maturidade" /><Metric label="Contas pedindo atenção" value={attention.length} detail="Lacunas, baixa atividade ou hipótese em validação" /><Metric label="Reuniões próximas" value={data.meetings.filter((item) => item.meetingStatus === "scheduled").length} detail="Briefings que devem ser revisados" /></div>
        <div className="v4-home-grid"><section className="v4-card v4-span-2"><CardHeader eyebrow="Fila proativa" title="Ações recomendadas" side={<span className="v4-live"><i /> Atualizada ao abrir</span>} /><div className="v4-action-list">{portfolioActions.slice(0, 7).map((action) => <ActionRow key={action.id} action={action} account={data.discoveries.find((item) => item.id === action.discoveryId)} onOpen={() => openAccount(action.discoveryId)} onStatus={(status) => mutate({ action: "action_status", id: action.discoveryId, actionId: action.id, status }, "Status da ação atualizado.")} readonly={!privateMode} />)}{!portfolioActions.length && <Empty text="Nenhuma ação pendente. A próxima informação poderá gerar novos sinais." />}</div></section><section className="v4-card"><CardHeader eyebrow="Carteira" title="Contas que pedem atenção" /><div className="v4-attention-list">{attention.slice(0, 6).map((account) => <button key={account.id} onClick={() => openAccount(account.id)}><span><strong>{account.customerName}</strong><small>{account.scores[0]?.short || "Contexto inicial"}</small></span><em>{account.progress}%</em></button>)}</div></section>
          <section className="v4-card"><CardHeader eyebrow="Mudanças recentes" title="Memória da carteira" /><div className="v4-timeline-mini">{data.accountEvents.slice(0, 5).map((event) => <button key={event.id} onClick={() => openAccount(event.discoveryId, "memory")}><i /><span><strong>{event.title}</strong><small>{data.discoveries.find((item) => item.id === event.discoveryId)?.customerName} · {formatDate(event.occurredAt)}</small></span></button>)}</div></section><section className="v4-card v4-span-2"><CardHeader eyebrow="Maturidade" title="Panorama da carteira" /><div className="v4-portfolio-bars">{data.discoveries.map((account) => <button key={account.id} onClick={() => openAccount(account.id)}><span>{account.customerName}</span><i><b style={{ width: `${account.progress}%` }} /></i><strong>{account.progress}%</strong><em>{account.stage}</em></button>)}</div></section></div>
      </section>}

      {active === "accounts" && selected && <section className="v4-page"><header className="v4-account-hero"><div><span>{selected.industry} · {selected.companySize}</span><h1>{selected.customerName}</h1><p>{memory?.executiveSummary || selected.challengeSummary}</p></div><div><Tag type={selected.priority === "Alta" ? "red" : selected.priority === "Média" ? "purple" : "gray"}>{selected.priority} prioridade</Tag><strong>{selected.progress}%</strong><small>Maturidade pré-CRM</small></div></header><nav className="v4-tabs" aria-label="Workspace da conta">{tabs.map((item) => <button key={item.id} className={tab === item.id ? "active" : ""} onClick={() => setTab(item.id)}>{item.label}</button>)}</nav>
        {tab === "summary" && <div className="v4-account-grid"><section className="v4-card v4-span-2"><CardHeader eyebrow="Memória executiva" title="O que importa agora" side={<Tag type="gray">{memory?.aiStatus || "fallback"}</Tag>} /><h2 className="v4-account-summary">{memory?.executiveSummary || selected.challengeSummary}</h2><div className="v4-change-strip">{memory?.changes.slice(0, 4).map((item) => <span key={item}>{item}</span>)}</div></section><section className="v4-card"><CardHeader eyebrow="Melhor próxima ação" title={actions[0]?.title || selected.nextEngagement} /><p>{actions[0]?.rationale || "Aprofunde o contexto da conta."}</p><button className="v4-inline" onClick={() => actions[0] && openAccount(selected.id, "plan")}>Abrir plano de ação <ArrowRight /></button></section><section className="v4-card"><CardHeader eyebrow="Hipóteses" title={`${hypotheses.length} em maturação`} /><div className="v4-hypothesis-mini">{hypotheses.slice(0, 3).map((item) => <div key={item.id}><Tag type={statusType(item.stage)}>{statusLabel[item.stage] || item.stage}</Tag><strong>{item.title}</strong><small>{item.confidence}% confiança</small></div>)}</div></section><section className="v4-card"><CardHeader eyebrow="Cobertura" title="Stakeholders" /><div className="v4-stakeholder-chips">{stakeholders.slice(0, 5).map((item) => <button key={item.id} onClick={() => { setSelectedStakeholderId(item.id); setTab("stakeholders"); }}><span>{item.name.split(" ").map((part) => part[0]).slice(0, 2)}</span><strong>{item.name}</strong><small>{item.role}</small></button>)}</div></section><section className="v4-card v4-span-2"><CardHeader eyebrow="Aderência IBM" title="Temas que merecem validação" /><CarbonCapabilityChart scores={selected.scores} /></section></div>}
        {tab === "memory" && <div className="v4-memory-layout"><section className="v4-card v4-span-2"><CardHeader eyebrow="Memória da conta" title="Sabemos, supomos e falta descobrir" side={<span className="v4-version">versão {memory?.version || 1}</span>} /><div className="v4-memory-board"><MemoryColumn title="Sabemos" tone="known" items={memory?.known || []} /><MemoryColumn title="Supomos" tone="assumption" items={memory?.assumptions || []} /><MemoryColumn title="Falta descobrir" tone="gap" items={memory?.gaps || []} /><MemoryColumn title="Desatualizado" tone="stale" items={accountEvents.filter((item) => item.evidenceStatus === "stale").map((item) => item.title)} /></div></section><section className="v4-card"><CardHeader eyebrow="Fontes" title="Timeline unificada" /><div className="v4-timeline">{accountEvents.map((event) => <article id={`source-${event.sourceId || event.id}`} key={event.id}><i className={event.evidenceStatus} /><div><span>{event.sourceType} · {event.confidence}%</span><strong>{event.title}</strong><p>{event.content}</p><small>{formatDate(event.occurredAt)}</small></div></article>)}</div></section><section className="v4-card"><CardHeader eyebrow="Documentos" title="Fontes da conta" side={privateMode ? <label className="v4-upload">Adicionar<input type="file" accept=".pdf,.docx,.txt,.md" onChange={(event) => event.target.files?.[0] && void uploadDocument(event.target.files[0], selected.id, mode, notify, load, setSaving)} /></label> : undefined} /><div className="v4-doc-list">{documents.map((doc) => <div key={doc.id}><Document /><span><strong>{doc.name}</strong><small>{doc.status} · {(doc.sizeBytes / 1024).toFixed(0)} KB</small></span></div>)}{!documents.length && <Empty text={privateMode ? "PDF, DOCX, TXT ou Markdown, até 15 MB." : "Documentos reais ficam disponíveis somente no workspace privado."} />}</div></section></div>}
        {tab === "meetings" && <div className="v4-account-grid"><section className="v4-card"><CardHeader eyebrow="Próxima reunião" title={meetings.find((item) => item.meetingStatus === "scheduled")?.title || "Agendar preparação"} /><MeetingSchedule accountId={selected.id} readonly={!privateMode} saving={saving} onSave={(payload) => mutate({ action: "information", id: selected.id, kind: "scheduled_meeting", ...payload }, "Reunião agendada e briefing gerado.")} /></section><section className="v4-card v4-span-2"><CardHeader eyebrow="Pós-reunião inteligente" title="Registrar notas livres" /><MeetingForm saving={saving} readonly={!privateMode} onSave={(payload) => mutate({ action: "meeting", id: selected.id, ...payload }, "Notas analisadas e memória atualizada.")} /></section><section className="v4-card v4-span-3"><CardHeader eyebrow="Histórico" title="Reuniões e briefings" /><div className="v4-meeting-list">{meetings.map((meeting) => <details key={meeting.id}><summary><span><Tag type={meeting.meetingStatus === "scheduled" ? "cyan" : meeting.aiStatus === "watsonx" ? "green" : "gray"}>{meeting.meetingStatus === "scheduled" ? "Agendada" : meeting.aiStatus}</Tag><strong>{meeting.title}</strong><small>{formatDate(meeting.scheduledAt || meeting.createdAt)}</small></span><ArrowRight /></summary><div><h3>{meeting.summary}</h3><p>{meeting.notes}</p><div className="v4-insight-columns"><List title="Sinais" items={meeting.insights.signals} /><List title="Perguntas" items={meeting.insights.nextQuestions} /><List title="Próximos passos" items={meeting.insights.nextActions} /></div></div></details>)}</div></section></div>}
        {tab === "stakeholders" && <div className="v4-org-layout"><section className="v4-card v4-org-card"><CardHeader eyebrow="Mapa de relacionamento" title="Organograma dinâmico" side={<Button size="sm" kind="tertiary" renderIcon={Add} disabled={!privateMode} onClick={() => { setEditStakeholder(null); setShowStakeholder(true); }}>Stakeholder</Button>} /><div className="v4-org-canvas"><div className="v4-org-roots">{stakeholders.filter((item) => !item.reportsToId || !stakeholders.some((person) => person.id === item.reportsToId)).map((person) => <OrgBranch key={person.id} person={person} people={stakeholders} selectedId={stakeholder?.id} collapsed={collapsed} onSelect={setSelectedStakeholderId} onToggle={(id) => setCollapsed((current) => { const next = new Set(current); if (next.has(id)) next.delete(id); else next.add(id); return next; })} />)}</div></div></section><aside className="v4-card v4-person-panel">{stakeholder ? <><div className="v4-person-head"><span>{stakeholder.name.split(" ").map((part) => part[0]).slice(0, 2)}</span><div><small>{stakeholder.role}</small><h2>{stakeholder.name}</h2><p>{stakeholder.area}</p></div></div><div><Tag type={stakeholder.stance === "Aliado" ? "green" : stakeholder.stance === "Resistente" ? "magenta" : "gray"}>{stakeholder.stance}</Tag> <Tag type="blue">Influência {stakeholder.influence}</Tag></div><hr /><small className="v4-eyebrow">Prioridades</small><div className="v4-priority-tags">{stakeholder.priorities.map((item) => <span key={item}>{item}</span>)}</div><small className="v4-eyebrow">Inteligência cruzada</small><h3>Abordagem sugerida</h3><p>{stakeholder.notes || `Conecte ${selected.scores[0]?.short} às prioridades desta pessoa e valide influência, postura e critérios de decisão.`}</p><blockquote>“{playbooks.find((item) => item.key === selected.scores[0]?.short)?.question || "Qual prioridade executiva devemos validar?"}”</blockquote>{privateMode && <button className="v4-inline" onClick={() => { setEditStakeholder(stakeholder); setShowStakeholder(true); }}>Editar perfil e relacionamento →</button>}</> : <Empty text="Selecione uma pessoa no organograma." />}</aside></div>}
        {tab === "themes" && <div className="v4-account-grid"><section className="v4-card v4-span-3"><CardHeader eyebrow="Heatmap individual" title="Valor, prontidão, confiança e evidências" /><CarbonCapabilityChart scores={selected.scores} /><div className="v4-score-table">{selected.scores.map((score) => <details key={score.short}><summary><span><strong>{score.name}</strong><small>{score.level}</small></span><meter min="0" max="100" value={score.alignment} /><em>{score.alignment}%</em></summary><div><List title="Evidências" items={score.evidence} /><p><b>Ação:</b> {score.action}</p></div></details>)}</div></section>{selected.scores.slice(0, 3).map((score) => { const book = playbooks.find((item) => item.key === score.short) || playbooks[0]; return <section className="v4-card" key={score.short}><CardHeader eyebrow={`${score.alignment}% alinhamento`} title={score.short} side={<Tag type={score.alignment >= 75 ? "green" : "purple"}>{score.confidence}% confiança</Tag>} /><h3>{book.product}</h3><p>{book.pitch}</p><small className="v4-eyebrow">Pergunta sugerida</small><blockquote>“{book.question}”</blockquote><footer>{book.workshop}</footer></section>; })}</div>}
        {tab === "plan" && <AccountPlanView key={plan?.updatedAt || selected.id} plan={plan} hypotheses={hypotheses} actions={actions} privateMode={privateMode} saving={saving} onAction={(status, actionId) => mutate({ action: "action_status", id: selected.id, actionId, status }, "Plano de ação atualizado.")} onSave={(payload) => mutate({ action: "plan_save", id: selected.id, ...payload }, "Account Plan salvo.")} onSuggest={() => mutate({ action: "plan_suggest", id: selected.id }, "Sugestão preparada para sua revisão.")} onApply={() => mutate({ action: "plan_apply", id: selected.id }, "Sugestão aprovada e aplicada ao plano.")} />}
      </section>}

      {active === "radar" && <section className="v4-page"><header className="v4-page-heading"><div><span>Radar da carteira</span><h1>Priorize contas, não apenas scores</h1><p>Compare aderência IBM, cobertura de relações, maturidade e lacunas de evidência.</p></div></header><section className="v4-card"><CardHeader eyebrow="Heatmap" title="Aderência por conta e capacidade" side={<Tag type="cyan">Carbon Charts</Tag>} /><div className="v4-heatmap"><div><strong>Conta</strong>{playbooks.map((item) => <span key={item.key}>{item.key}</span>)}</div>{data.discoveries.map((account) => <button key={account.id} onClick={() => openAccount(account.id, "themes")}><strong>{account.customerName}<small>{account.progress}% madura</small></strong>{playbooks.map((book) => { const score = account.scores.find((item) => item.short === book.key)?.alignment || 0; return <i key={book.key} data-level={score >= 75 ? "high" : score >= 50 ? "medium" : "low"} style={{ opacity: Math.max(.25, score / 100) }} title={`${book.key}: ${score}%`}><em>{score}</em></i>; })}</button>)}</div></section><div className="v4-radar-grid"><section className="v4-card"><CardHeader eyebrow="Cobertura" title="Mapa político" /><div className="v4-portfolio-bars">{data.discoveries.map((account) => { const people = data.stakeholders.filter((item) => item.discoveryId === account.id); const confirmed = people.filter((item) => item.source === "manual").length; return <button key={account.id} onClick={() => openAccount(account.id, "stakeholders")}><span>{account.customerName}</span><i><b style={{ width: `${Math.min(100, confirmed * 22)}%` }} /></i><strong>{confirmed}</strong><em>confirmados</em></button>; })}</div></section><section className="v4-card"><CardHeader eyebrow="Lacunas" title="Informação que falta" /><div className="v4-gap-list">{data.memories.flatMap((item) => item.gaps.slice(0, 2).map((gap) => ({ gap, account: data.discoveries.find((account) => account.id === item.discoveryId) }))).slice(0, 8).map((item, index) => <button key={`${item.account?.id}-${index}`} onClick={() => item.account && openAccount(item.account.id, "memory")}><Asleep /><span><strong>{item.gap}</strong><small>{item.account?.customerName}</small></span></button>)}</div></section></div></section>}

      {active === "settings" && <section className="v4-page"><header className="v4-page-heading"><div><span>Configurações</span><h1>Governança, integrações e auditoria</h1><p>Controles administrativos ficam aqui; origem, confiança e status da IA continuam visíveis em cada insight.</p></div></header><div className="v4-settings-grid"><section className="v4-card"><CardHeader eyebrow="Status da IA" title="Watsonx + fallback obrigatório" /><div className="v4-system-status"><div><i className="fallback" /><span><strong>Motor determinístico</strong><small>Ativo e cobrindo memória, fila, hipóteses e respostas</small></span><Tag type="green">Operacional</Tag></div><div><i /><span><strong>IBM watsonx.ai</strong><small>Usado automaticamente quando as quatro variáveis são configuradas</small></span><Tag type={data.meetings.some((item) => item.aiStatus === "watsonx") ? "green" : "gray"}>{data.meetings.some((item) => item.aiStatus === "watsonx") ? "Ativo" : "Não configurado"}</Tag></div></div></section><section className="v4-card"><CardHeader eyebrow="Integrações" title="Conectores preparados" /><div className="v4-system-status">{[["OpenAI Sites + D1 + R2", "Aplicação, dados estruturados e documentos"], ["CRM", "Handoff somente após aprovação humana"], ["Sign in with ChatGPT", "Autenticação do workspace privado"]].map(([name, detail]) => <div key={name}><i className="fallback" /><span><strong>{name}</strong><small>{detail}</small></span><Tag type="blue">Preparado</Tag></div>)}</div></section><section className="v4-card"><CardHeader eyebrow="Governança" title="Controles ativos" /><div className="v4-control-list">{["Autorização por conta no servidor", "Demonstração pública somente leitura", "Fontes e confiança em cada recomendação", "Nenhuma alteração ou handoff sem aprovação", "Migrations aditivas e rollback para V3"].map((item) => <div key={item}><span>✓</span>{item}</div>)}</div></section><section className="v4-card"><CardHeader eyebrow="Auditoria" title="Execuções recentes" /><div className="v4-audit">{data.aiRuns.slice(0, 8).map((run) => <div key={run.id}><span><strong>{run.agent}</strong><small>{run.provider} · {run.confidence}% confiança</small></span><Tag type={run.status === "completed" ? "green" : "red"}>{run.status}</Tag></div>)}</div></section></div></section>}
    </main>

    <aside className="v4-copilot" aria-hidden={!copilot}><header><div><span>Pergunte sobre esta conta</span><strong>{selected?.customerName || "Selecione uma conta"}</strong></div><button onClick={() => setCopilot(false)} aria-label="Fechar copiloto"><Close /></button></header><div className="v4-copilot-body"><div className="v4-agent-note"><i />O copiloto responde apenas com dados da conta, separa evidência de inferência e nunca altera registros sem confirmação.</div>{chatResult ? <div className="v4-answer"><Tag type={chatResult.aiStatus === "watsonx" ? "green" : "gray"}>{chatResult.aiStatus}</Tag><p>{chatResult.answer}</p><strong>{chatResult.confidence}% de confiança</strong><div>{chatResult.citations.map((cite, index) => <a key={`${cite.sourceId}-${index}`} href={`#source-${cite.sourceId}`} onClick={() => { setActive("accounts"); setTab("memory"); setCopilot(false); }}><span>{index + 1}</span>{cite.title}<small>{cite.excerpt}</small></a>)}</div></div> : <div className="v4-suggested-questions">{["O que sabemos sobre a estratégia de cloud?", "Quem pode patrocinar uma conversa de FinOps?", "Quais informações ainda estão faltando?", "O que mudou desde a última reunião?"].map((item) => <button key={item} onClick={() => setQuestion(item)}>{item}</button>)}</div>}</div><form onSubmit={ask}><textarea value={question} onChange={(event) => setQuestion(event.target.value)} placeholder="Pergunte sobre evidências, pessoas ou próximos passos…" rows={3} /><button disabled={saving || !selected || !question.trim()}><ArrowRight /></button></form></aside>

    {showNew && <Modal title="Nova conta" eyebrow="Workspace privado" onClose={() => setShowNew(false)}><form onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); void mutate({ action: "create", customerName: form.get("customerName"), industry: form.get("industry"), companySize: form.get("companySize") }, "Conta criada.").then(() => setShowNew(false)); }}><label>Empresa<input name="customerName" required /></label><label>Setor<input name="industry" required /></label><label>Porte<select name="companySize"><option>Enterprise</option><option>Large</option><option>Mid-market</option></select></label><button className="v4-primary-button" disabled={saving}>Criar conta</button></form></Modal>}
    {showAdd && selected && <Modal title="Adicionar informação" eyebrow={selected.customerName} onClose={() => setShowAdd(false)}><AddInformation saving={saving} onSave={(payload) => void mutate({ action: "information", id: selected.id, ...payload }, "Informação salva; memória e próximos passos recalculados.").then(() => setShowAdd(false))} /></Modal>}
    {showStakeholder && selected && <Modal title={editStakeholder ? "Editar stakeholder" : "Adicionar stakeholder"} eyebrow={`Mapa de relacionamento · ${selected.customerName}`} onClose={() => setShowStakeholder(false)}><StakeholderForm stakeholder={editStakeholder} people={stakeholders} saving={saving} onSave={(payload) => void mutate({ action: "stakeholder_upsert", id: selected.id, stakeholderId: editStakeholder?.id, ...payload }, "Stakeholder salvo e inteligência cruzada atualizada.").then(() => setShowStakeholder(false))} /></Modal>}
    {privateMode && active === "accounts" && <button className="v4-floating-add" onClick={() => setShowNew(true)}><Add /> Nova conta</button>}
  </div>;
}

function Metric({ label, value, detail }: { label: string; value: number; detail: string }) { return <article className="v4-metric"><span>{label}</span><strong>{value}</strong><small>{detail}</small></article>; }
function CardHeader({ eyebrow, title, side }: { eyebrow: string; title: string; side?: React.ReactNode }) { return <header className="v4-card-head"><div><span>{eyebrow}</span><h2>{title}</h2></div>{side}</header>; }
function Empty({ text }: { text: string }) { return <div className="v4-empty"><span>◇</span><p>{text}</p></div>; }
function List({ title, items }: { title: string; items: string[] }) { return <div className="v4-list"><strong>{title}</strong>{items?.length ? <ul>{items.map((item) => <li key={item}>{item}</li>)}</ul> : <small>Sem informação suficiente.</small>}</div>; }
function MemoryColumn({ title, items, tone }: { title: string; items: string[]; tone: string }) { return <section className={tone}><header><i />{title}<em>{items.length}</em></header>{items.map((item) => <p key={item}>{item}</p>)}{!items.length && <small>Nenhum item nesta categoria.</small>}</section>; }
function ActionRow({ action, account, onOpen, onStatus, readonly }: { action: Action; account?: Discovery; onOpen: () => void; onStatus: (status: string) => void; readonly: boolean }) { return <article><button className="v4-action-main" onClick={onOpen}><span className={`v4-priority p${Math.round(action.priorityScore / 10)}`}>{action.priorityScore}</span><div><small>{account?.customerName} · {action.type.replaceAll("_", " ")}</small><strong>{action.title}</strong><p>{action.rationale}</p><em>{action.nextStep}</em></div></button><div><Tag type={statusType(action.status)}>{statusLabel[action.status] || action.status}</Tag><small>{formatDate(action.dueAt)}</small>{!readonly && action.status === "proposal" && <><button onClick={() => onStatus("accepted")}>Aceitar</button><button onClick={() => onStatus("discarded")}>Descartar</button></>}{!readonly && action.status === "accepted" && <button onClick={() => onStatus("in_progress")}>Iniciar</button>}{!readonly && action.status === "in_progress" && <button onClick={() => onStatus("completed")}>Concluir</button>}</div></article>; }

function MeetingForm({ onSave, saving, readonly }: { onSave: (payload: Record<string, unknown>) => void; saving: boolean; readonly: boolean }) { return <form className="v4-form" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); onSave({ title: form.get("title"), notes: form.get("notes"), attendees: form.get("attendees") }); }}><label>Título<input name="title" defaultValue="Reunião de account intelligence" disabled={readonly} /></label><label>Participantes<input name="attendees" placeholder="CFO, CIO, Ana Souza" disabled={readonly} /></label><label>Notas<textarea name="notes" required rows={7} placeholder="Contexto, falas, dores, sistemas, compromissos e dúvidas…" disabled={readonly} /></label><button className="v4-primary-button" disabled={saving || readonly}>{saving ? "Analisando…" : "Salvar e analisar"}</button></form>; }
function MeetingSchedule({ accountId, onSave, saving, readonly }: { accountId: string; onSave: (payload: Record<string, unknown>) => void; saving: boolean; readonly: boolean }) { return <form key={accountId} className="v4-form" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); onSave({ title: form.get("title"), content: form.get("objective"), occurredAt: new Date(String(form.get("date"))).toISOString(), attendees: form.get("attendees") }); }}><label>Reunião<input name="title" required placeholder="Revisão de estratégia cloud" disabled={readonly} /></label><label>Data e hora<input name="date" type="datetime-local" required disabled={readonly} /></label><label>Participantes<input name="attendees" placeholder="CIO, Finanças" disabled={readonly} /></label><label>Objetivo<textarea name="objective" required rows={3} placeholder="O que precisamos aprender ou validar?" disabled={readonly} /></label><button className="v4-primary-button" disabled={saving || readonly}>Gerar preparação</button></form>; }
function AddInformation({ onSave, saving }: { onSave: (payload: Record<string, unknown>) => void; saving: boolean }) { const [kind, setKind] = useState("note"); return <form className="v4-form" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); onSave({ kind, title: form.get("title"), content: form.get("content"), evidenceStatus: form.get("evidenceStatus") }); }}><label>Tipo<select value={kind} onChange={(event) => setKind(event.target.value)}><option value="note">Anotação</option><option value="discovery_answer">Resposta</option><option value="initiative">Iniciativa</option><option value="system">Sistema</option><option value="pain">Dor</option><option value="risk">Risco</option><option value="objective">Objetivo</option><option value="commitment">Compromisso</option><option value="contradiction">Contradição a revisar</option><option value="partner">Parceiro</option><option value="competitor">Concorrente</option></select></label><label>{kind === "discovery_answer" ? "Pergunta de descoberta" : "Título"}<input name="title" list={kind === "discovery_answer" ? "discovery-questions" : undefined} required placeholder={kind === "discovery_answer" ? "Escolha ou escreva uma pergunta" : "Resumo curto"} /><datalist id="discovery-questions">{questions.map((item) => <option key={item[0]} value={item[1]} />)}</datalist></label><label>Informação<textarea name="content" rows={7} required placeholder="Descreva o que foi observado e a fonte…" /></label><label>Natureza<select name="evidenceStatus"><option value="confirmed">Evidência confirmada</option><option value="assumption">Hipótese a validar</option><option value="gap">Lacuna / falta descobrir</option><option value="stale">Informação desatualizada</option></select></label><button className="v4-primary-button" disabled={saving}>Salvar e recalcular</button></form>; }
function StakeholderForm({ stakeholder, people, onSave, saving }: { stakeholder: Stakeholder | null; people: Stakeholder[]; onSave: (payload: Record<string, unknown>) => void; saving: boolean }) { return <form className="v4-form" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); onSave(Object.fromEntries(form.entries())); }}><div className="v4-form-row"><label>Nome<input name="name" defaultValue={stakeholder?.name} required /></label><label>Cargo<input name="role" defaultValue={stakeholder?.role} required /></label></div><div className="v4-form-row"><label>Área<input name="area" defaultValue={stakeholder?.area} /></label><label>Reporta para<select name="reportsToId" defaultValue={stakeholder?.reportsToId || ""}><option value="">Topo / não mapeado</option>{people.filter((item) => item.id !== stakeholder?.id).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div><div className="v4-form-row"><label>Influência<select name="influence" defaultValue={stakeholder?.influence || "Média"}><option>Alta</option><option>Média</option><option>Baixa</option></select></label><label>Postura<select name="stance" defaultValue={stakeholder?.stance || "Desconhecido"}><option>Aliado</option><option>Neutro</option><option>Resistente</option><option>Desconhecido</option></select></label></div><label>Prioridades<input name="priorities" defaultValue={stakeholder?.priorities.join(", ")} /></label><label>Contexto e plano de relacionamento<textarea name="notes" rows={5} defaultValue={stakeholder?.notes} /></label><button className="v4-primary-button" disabled={saving}>Salvar stakeholder</button></form>; }

function OrgBranch({ person, people, selectedId, collapsed, onSelect, onToggle }: { person: Stakeholder; people: Stakeholder[]; selectedId?: string; collapsed: Set<string>; onSelect: (id: string) => void; onToggle: (id: string) => void }) { const reports = people.filter((item) => item.reportsToId === person.id); return <div className="v4-org-branch"><button className={`v4-org-person ${selectedId === person.id ? "selected" : ""}`} onClick={() => onSelect(person.id)}><span>{person.name.split(" ").map((part) => part[0]).slice(0, 2)}</span><div><small>{person.area}</small><strong>{person.name}</strong><em>{person.role}</em></div><i className={person.stance.toLowerCase()} />{reports.length > 0 && <b onClick={(event) => { event.stopPropagation(); onToggle(person.id); }}>{collapsed.has(person.id) ? "+" : "−"}{reports.length}</b>}</button>{reports.length > 0 && !collapsed.has(person.id) && <div className="v4-org-children">{reports.map((item) => <OrgBranch key={item.id} person={item} people={people} selectedId={selectedId} collapsed={collapsed} onSelect={onSelect} onToggle={onToggle} />)}</div>}</div>; }
function AccountPlanView({ plan, hypotheses, actions, privateMode, saving, onAction, onSave, onSuggest, onApply }: { plan?: Plan; hypotheses: Hypothesis[]; actions: Action[]; privateMode: boolean; saving: boolean; onAction: (status: string, id: string) => void; onSave: (payload: Record<string, unknown>) => void; onSuggest: () => void; onApply: () => void }) { const [draft, setDraft] = useState<Record<string, string>>(() => plan ? Object.fromEntries(["priorities", "initiatives", "objectives", "risks", "ecosystem", "relationship", "plan30", "plan60", "plan90"].map((key) => [key, (plan[key as keyof Plan] as string[] || []).join("\n")])) : {}); return <div className="v4-plan-layout"><section className="v4-card v4-span-2"><CardHeader eyebrow="Account Plan" title="Plano humano, enriquecido por IA" side={<div className="v4-plan-buttons"><Button size="sm" kind="tertiary" disabled={!privateMode || saving} onClick={onSuggest}>Gerar sugestão</Button><Button size="sm" disabled={!privateMode || saving} onClick={() => onSave(draft)}>Salvar plano</Button></div>} /><div className="v4-plan-fields">{[["priorities", "Prioridades estratégicas"], ["initiatives", "Iniciativas"], ["objectives", "Objetivos e métricas"], ["risks", "Riscos"], ["ecosystem", "Parceiros e concorrentes"], ["relationship", "Plano de relacionamento"]].map(([key, label]) => <label key={key}>{label}<textarea value={draft[key] || ""} onChange={(event) => setDraft((current) => ({ ...current, [key]: event.target.value }))} rows={4} disabled={!privateMode} /></label>)}</div><div className="v4-plan-horizons">{[["plan30", "30 dias"], ["plan60", "60 dias"], ["plan90", "90 dias"]].map(([key, label]) => <label key={key}><span>{label}</span><textarea value={draft[key] || ""} onChange={(event) => setDraft((current) => ({ ...current, [key]: event.target.value }))} rows={6} disabled={!privateMode} /></label>)}</div></section><aside><section className="v4-card"><CardHeader eyebrow="Proposta da IA" title="Comparar antes de aplicar" side={<Tag type="purple">{plan?.approvalStatus || "draft"}</Tag>} />{plan?.suggestion && Object.keys(plan.suggestion).length ? <><div className="v4-suggestion">{Object.entries(plan.suggestion).slice(0, 5).map(([key, items]) => <div key={key}><strong>{key}</strong>{items.map((item) => <p key={item}>+ {item}</p>)}</div>)}</div><button className="v4-primary-button" disabled={!privateMode} onClick={onApply}>Aprovar e aplicar</button></> : <Empty text="Gere uma sugestão; o conteúdo humano só muda após aprovação." />}</section><section className="v4-card"><CardHeader eyebrow="Hipóteses" title="Maturidade pré-CRM" />{hypotheses.map((item) => <details className="v4-hypothesis" key={item.id}><summary><Tag type={statusType(item.stage)}>{statusLabel[item.stage] || item.stage}</Tag><strong>{item.capabilityKey}</strong><em>{item.confidence}%</em></summary><p>{item.problem}</p><List title="Lacunas" items={item.gaps} /><small>{item.nextStep}</small></details>)}</section><section className="v4-card"><CardHeader eyebrow="Fila" title="Próximas ações" />{actions.slice(0, 5).map((item) => <div className="v4-plan-action" key={item.id}><span><strong>{item.title}</strong><small>{statusLabel[item.status]}</small></span>{privateMode && item.status === "proposal" && <button onClick={() => onAction("accepted", item.id)}>Aceitar</button>}</div>)}</section></aside></div>; }
function Modal({ title, eyebrow, onClose, children }: { title: string; eyebrow: string; onClose: () => void; children: React.ReactNode }) { return <div className="v4-modal-backdrop" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><div className="v4-modal" role="dialog" aria-modal="true"><header><span>{eyebrow}</span><h2>{title}</h2><button onClick={onClose} aria-label="Fechar"><Close /></button></header>{children}</div></div>; }

async function uploadDocument(file: File, accountId: string, mode: string, notify: (value: string) => void, reload: () => Promise<void>, setSaving: (value: boolean) => void) {
  if (file.size > 15 * 1024 * 1024) { notify("O arquivo excede o limite de 15 MB."); return; } setSaving(true);
  try { const extracted = await extractText(file); const form = new FormData(); form.append("file", file); form.append("extractedText", extracted.text); form.append("pagesJson", JSON.stringify(extracted.pages)); form.append("scope", mode); const response = await fetch(`/api/accounts/${accountId}/documents`, { method: "POST", body: form }); const payload = await response.json() as { error?: string }; if (!response.ok) throw new Error(payload.error || "Falha no upload"); await reload(); notify(extracted.text ? "Documento adicionado à memória com citações." : "Documento salvo; este PDF requer resumo manual."); } catch (error) { notify(error instanceof Error ? error.message : "Não foi possível processar o documento."); } finally { setSaving(false); }
}
async function extractText(file: File): Promise<{ text: string; pages: Array<{ page: number; text: string }> }> {
  const extension = file.name.split(".").pop()?.toLowerCase(); if (extension === "txt" || extension === "md") { const text = await file.text(); return { text, pages: [{ page: 1, text }] }; }
  if (extension === "docx") { const mammoth = await import("mammoth/mammoth.browser"); const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() }); return { text: result.value, pages: [{ page: 1, text: result.value }] }; }
  if (extension === "pdf") { const pdfjs = await import("pdfjs-dist"); pdfjs.GlobalWorkerOptions.workerSrc = new URL("pdfjs-dist/build/pdf.worker.min.mjs", import.meta.url).toString(); const pdf = await pdfjs.getDocument({ data: new Uint8Array(await file.arrayBuffer()) }).promise; const pages = []; for (let index = 1; index <= pdf.numPages; index += 1) { const page = await pdf.getPage(index); const content = await page.getTextContent(); const text = content.items.map((item) => "str" in item ? item.str : "").join(" "); pages.push({ page: index, text }); } return { text: pages.map((page) => page.text).join("\n\n"), pages }; }
  throw new Error("Tipo de arquivo não suportado.");
}
